// src/components/ide/formatSdev.ts
function formatSdev(code, indentSize = 2) {
  const lines = code.split("\n");
  const indentUnit = " ".repeat(indentSize);
  let depth = 0;
  const out = [];
  for (const raw of lines) {
    const line = raw.replace(/\s+$/, "");
    const trimmed = line.trim();
    let opens2 = 0, closes2 = 0;
    let inStr = null;
    for (let i = 0; i < trimmed.length; i++) {
      const ch = trimmed[i], nx = trimmed[i + 1];
      if (inStr) {
        if (ch === "\\") {
          i++;
          continue;
        }
        if (ch === inStr) inStr = null;
        continue;
      }
      if (ch === '"' || ch === "'") {
        inStr = ch;
        continue;
      }
      if (ch === "/" && nx === "/") break;
      if (ch === ":" && nx === ":") {
        opens2++;
        i++;
      } else if (ch === ";" && nx === ";") {
        closes2++;
        i++;
      }
    }
    const startCloses = trimmed.startsWith(";;") ? 1 : 0;
    const localDepth = Math.max(0, depth - startCloses);
    if (trimmed === "") {
      out.push("");
    } else {
      out.push(indentUnit.repeat(localDepth) + trimmed);
    }
    depth = Math.max(0, depth + opens2 - closes2);
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n");
}

