// cli/prompt.ts
import { createInterface } from "node:readline";
function ask(question) {
  return new Promise((res) => {
    const rl = createInterface({ input: process.stdin, output: process.stdout, terminal: true });
    rl.question(question, (answer) => {
      rl.close();
      res(answer.trim());
    });
  });
}
function askHidden(question) {
  const stdin = process.stdin;
  if (!stdin.isTTY) return ask(question);
  return new Promise((res, rej) => {
    process.stdout.write(question);
    stdin.setRawMode(true);
    stdin.resume();
    stdin.setEncoding("utf8");
    let buffer = "";
    const finish2 = (value2) => {
      stdin.setRawMode(false);
      stdin.pause();
      stdin.removeListener("data", onData);
      process.stdout.write("\n");
      if (value2 === null) rej(new Error("cancelled"));
      else res(value2);
    };
    const onData = (chunk) => {
      for (const ch of chunk) {
        if (ch === "\r" || ch === "\n") return finish2(buffer);
        if (ch === "") return finish2(null);
        if (ch === "\x7F" || ch === "\b") {
          if (buffer.length) {
            buffer = buffer.slice(0, -1);
            process.stdout.write("\b \b");
          }
          continue;
        }
        if (ch < " ") continue;
        buffer += ch;
        process.stdout.write("*");
      }
    };
    stdin.on("data", onData);
  });
}
async function password(explicit, label = "password: ") {
  if (explicit) return explicit;
  if (process.env.SDEV_PASSWORD) return process.env.SDEV_PASSWORD;
  const value2 = await askHidden(label);
  if (!value2) throw new Error("no password entered");
  return value2;
}

