var DIRECTIVE_RE = /^\s*!#\s*agent\s*:\s*([a-z]+)(?:\s*:\s*([a-z]+))?\s*$/i;
function scanDirectives(source) {
  let mode = null;
  let brain = null;
  let learn = null;
  let found = false;
  const lines = source.split("\n").map((line) => {
    const m2 = line.match(DIRECTIVE_RE);
    if (!m2) return line;
    found = true;
    const head2 = m2[1].toLowerCase();
    const tail = (m2[2] ?? "").toLowerCase();
    switch (head2) {
      case "off":
        mode = "off";
        break;
      case "on":
        mode = mode === "off" ? "on" : mode ?? "on";
        break;
      case "auto":
        mode = mode ?? "auto";
        brain = "auto";
        break;
      case "strict":
        mode = "strict";
        break;
      case "local":
        brain = "local";
        mode = mode ?? "on";
        break;
      case "online":
        brain = "online";
        mode = mode ?? "on";
        break;
      case "nobrain":
      case "rules":
        brain = "none";
        break;
      case "learn":
        learn = tail !== "off" && tail !== "no";
        break;
      default:
        break;
    }
    return "";
  });
  return { mode, brain, learn, found, source: lines.join("\n") };
}

