var VERSION = "5.1.0";
var SITE = "https://web.sdev.codes";

// cli/update.ts
import { existsSync as existsSync5, readFileSync as readFileSync5, writeFileSync as writeFileSync4, renameSync, chmodSync as chmodSync2, mkdirSync as mkdirSync3 } from "node:fs";
