function createProjectFiles(targetDir, name, templateKey, isInit = false) {
  const tmpl = PROJECT_TEMPLATES[templateKey] ?? PROJECT_TEMPLATES.console;
  if (!PROJECT_TEMPLATES[templateKey]) {
    console.warn(`Template "${templateKey}" not found. Falling back to "console" (options: console, game, hardware, ml).`);
  }
  mkdirSync5(targetDir, { recursive: true });
  const manifestPath = resolve6(targetDir, "sdev.json");
  if (existsSync6(manifestPath)) {
    die(`sdev.json already exists in ${targetDir}`);
  }
  const manifest = {
    name,
    version: "0.1.0",
    description: tmpl.description,
    template: templateKey in PROJECT_TEMPLATES ? templateKey : "console",
    runtime: tmpl.runtime,
    entry: "main.sdev",
    libraries: [],
    dialects: []
  };
  writeFileSync6(manifestPath, JSON.stringify(manifest, null, 2) + "\n");
  const mainPath = resolve6(targetDir, "main.sdev");
  if (!existsSync6(mainPath)) {
    writeFileSync6(mainPath, tmpl.code.replace(/\{name\}/g, name));
  }
  const readmePath = resolve6(targetDir, "README.md");
  if (!existsSync6(readmePath)) {
    const readme = `# ${name}

${tmpl.description}

## Getting Started

Run the program:
\`\`\`bash
sdev run
\`\`\`

Or run the entry file directly:
\`\`\`bash
sdev run main.sdev
\`\`\`

Check syntax:
\`\`\`bash
sdev check main.sdev
\`\`\`

Static analysis and lint:
\`\`\`bash
sdev lint main.sdev
\`\`\`
`;
    writeFileSync6(readmePath, readme);
  }
  console.log(`\u2713 Initialized SDEV project "${name}" [template: ${templateKey in PROJECT_TEMPLATES ? templateKey : "console"}, runtime: ${tmpl.runtime}]`);
  console.log(`  - sdev.json`);
  console.log(`  - main.sdev`);
  console.log(`  - README.md`);
  console.log("\nTo get started:");
  if (!isInit) {
    console.log(`  cd ${name}`);
  }
  console.log("  sdev run");
}
function cmdNew(name) {
  if (!name) die("sdev new <project-name> [--template console|game|hardware|ml]");
  const targetDir = resolve6(process.cwd(), name);
  if (existsSync6(targetDir)) {
    die(`directory "${name}" already exists`);
  }
  const tmpl = value("--template", "-t") ?? "console";
  createProjectFiles(targetDir, name, tmpl, false);
}
function cmdInit() {
  const targetDir = process.cwd();
  const name = basename2(targetDir);
  const tmpl = value("--template", "-t") ?? "console";
  createProjectFiles(targetDir, name, tmpl, true);
}
async function main() {
  const pos = positionals();
  const cmd = pos[0];
  if (!cmd || flag("--help", "-h")) return help();
  if (flag("--version", "-v")) return console.log("sdev v" + VERSION);
  if (cmd !== "update") void maybeNotifyUpdate();
  switch (cmd) {
    case "update":
      return runUpdate(flag("--force"));
    case "new":
      return cmdNew(pos[1]);
    case "init":
      return cmdInit();
    case "run":
    case "exec":
      return cmdRun(pos[1]);
    case "repl":
      return cmdRepl();
    case "watch":
      return cmdWatch(pos[1] ?? die("sdev watch <file>"));
    case "check": {
      parseFile(pos[1] ?? die("sdev check <file>"), runOptions());
      console.log("OK \u2014 no syntax errors");
      return;
    }
    case "ast": {
      const { ast } = parseFile(pos[1] ?? die("sdev ast <file>"), runOptions());
      emit(JSON.stringify(ast, null, 2));
      return;
    }
    case "fmt": {
      const file = pos[1] ?? die("sdev fmt <file>");
      const raw = readSource(file);
      const formatted = formatSdev(stripSignature(raw));
      if (flag("-w", "--write")) {
        const sig = readSignature(raw);
        writeFileSync6(resolve6(process.cwd(), file), sig ? repairSignature(raw.split("\n")[0] + "\n" + formatted) : formatted);
        console.log("formatted", basename2(file));
      } else process.stdout.write(formatted.endsWith("\n") ? formatted : formatted + "\n");
      return;
    }
    case "compile":
      return cmdCompile(pos[1] ?? die("sdev compile <file>"));
    case "build-web":
    case "web":
      return cmdBuildWeb(pos[1] ?? die("sdev build-web <file.sdev> [-o index.html]"));
    case "run-bc":
      return cmdRunBc(pos[1] ?? die("sdev run-bc <file.sdevc>"));
    case "disasm":
      return cmdDisasm(pos[1] ?? die("sdev disasm <file>"));
    case "native":
      return cmdNative(pos[1] ?? die("sdev native <file>"));
    case "info":
      return cmdInfo(pos[1] ?? die("sdev info <file>"));
    case "sign":
      return cmdSign(pos[1] ?? "show", pos[2] ?? die("sdev sign <show|stamp|verify|strip> <file>"));
    case "agent":
      return cmdAgent(pos[1], pos.slice(2));
    case "dialect":
      return cmdDialect(pos[1], pos.slice(2));
    case "ext":
      return cmdExt(pos[1], pos.slice(2));
    case "lib":
      return cmdLib(pos[1], pos.slice(2));
    case "edit":
    case "ide":
      return cmdEdit(pos[1]);
    case "auth":
    case "login":
      return cmdAuth(cmd === "login" ? "login" : pos[1] ?? "whoami", cmd === "login" ? pos.slice(1) : pos.slice(2));
    case "logout":
      return cmdAuth("logout", []);
    case "whoami":
      return cmdAuth("whoami", []);
    case "cloud":
      return cmdCloud(pos[1], pos.slice(2));
    case "runtime": {
      const rt = pos[1];
      if (rt === "v1" || rt === "v2") {
        setRuntimePreference(rt);
        console.log("default runtime:", rt);
      } else console.log("default runtime:", runtimePreference());
      return;
    }
    case "languages":
      for (const l of SUPPORTED_LANGUAGES) console.log(" -", l);
      return;
    case "translate": {
      const file = pos[1] ?? die("sdev translate <file> --to <Language>");
      const to = value("--to") ?? die("--to <Language> is required");
      const src = stripSignature(readSource(file));
      const from = value("--from") ?? detectLanguage(src) ?? "English";
      emit(translateSource(src, from, to).translated);
      return;
    }
    case "home":
      console.log(SDEV_HOME);
      return;
    case "doctor":
      return cmdDoctor();
    case "explain":
      return cmdExplain(pos[1] ?? die("sdev explain <CODE|name>"));
    case "lint":
      return cmdLint(pos[1] ?? die("sdev lint <file.sdev>"));
    case "api":
      return cmdApi(pos[1]);
    case "version":
      console.log("sdev v" + VERSION);
      return;
    case "help":
      return help();
    default: {
      if (existsSync6(resolve6(process.cwd(), cmd))) return cmdRun(cmd);
      console.error(`unknown command "${cmd}"`);
      help();
      process.exit(1);
    }
  }
}
main().catch((e) => {
  console.error("error:", e instanceof Error ? e.message : String(e));
  process.exit(1);
});
